"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["78951"],{80016(e){e.exports=JSON.parse('{"id":"F329","slug":"straddle-strangle","name":"Straddle and Strangle","subject":"Derivatives","section":"Derivatives","topic":"Option strategies: spreads, straddles, strangles, collars","level":"Intermediate","aliases":["long volatility","option strategies","straddle breakeven","strangle breakeven"],"formula":{"latex":"\\\\text{Straddle profit}=|S_{T}-K|-(C+P)","also":[],"text":"Straddle (buy a call and a put at the same strike): Profit = |ST - K| - total premium; Strangle (put at a lower strike, call at a higher strike): Profit = max(Kp - ST, 0) + max(ST - Kc, 0) - total premium"},"symbols":[{"symbol":"K","meaning":"Strike of both options in a straddle","unit":"money"},{"symbol":"K_p, K_c","meaning":"Strikes of the put and call in a strangle, with Kp below Kc","unit":"money"},{"symbol":"C, P","meaning":"Premiums paid","unit":"money"},{"symbol":"S_T","meaning":"Price at expiry","unit":"money"}],"when_to_use":"Use it when you expect a big move but not its direction. Both strategies lose the premium if the price stays near the strikes, and profit from a large move either way. A strangle costs less than a straddle but needs a bigger move.","worked_example":{"problem":"A stock is at 100. A straddle at strike 100 costs 5 for the call and 4 for the put. A strangle with a 95 put and 105 call costs 1.80 and 2.50. The stock ends at 112. What are the profits and breakevens?","inputs":{"k":100,"c":5,"p":4,"kp":95,"kc":105,"cc":2.5,"pp":1.8,"st":112},"steps":[{"label":"Straddle cost = call + put","working":"5+4","value":"9.00"},{"label":"Straddle lower breakeven = K - cost","working":"100-9","value":"91.00"},{"label":"Straddle upper breakeven = K + cost","working":"100+9","value":"109.00"},{"label":"Straddle profit at expiry","working":null,"value":"3.00"},{"label":"Strangle cost","working":"2.5+1.8","value":"4.30"},{"label":"Strangle lower breakeven = Kp - cost","working":"95-4.3","value":"90.70"},{"label":"Strangle upper breakeven = Kc + cost","working":"105+4.3","value":"109.30"},{"label":"Strangle profit at expiry","working":"max(95-112, 0)+max(112-105, 0)-4.3","value":"2.70"}],"answer":"The straddle costs 9.00 and its breakevens are 91.00 and 109.00. At 112 it earns 3.00. The strangle costs 4.30, with breakevens at 90.70 and 109.30, and earns 2.70."},"calculator":{"available":true,"inputs":[{"id":"k","label":"Straddle strike","unit":"money","type":"number","default":100,"hint":""},{"id":"c","label":"Straddle call premium","unit":"money","type":"number","default":5,"hint":""},{"id":"p","label":"Straddle put premium","unit":"money","type":"number","default":4,"hint":""},{"id":"kp","label":"Strangle put strike","unit":"money","type":"number","default":95,"hint":""},{"id":"kc","label":"Strangle call strike","unit":"money","type":"number","default":105,"hint":""},{"id":"cc","label":"Strangle call premium","unit":"money","type":"number","default":2.5,"hint":""},{"id":"pp","label":"Strangle put premium","unit":"money","type":"number","default":1.8,"hint":""},{"id":"st","label":"Price at expiry","unit":"money","type":"number","default":112,"hint":""}],"checks":[{"expr":"kp<kc","message":"The strangle put strike must be below the call strike."}],"steps":[{"id":"sc","label":"Straddle cost = call + put","expr":"c+p","format":"money"},{"id":"slo","label":"Straddle lower breakeven = K - cost","expr":"k-sc","format":"money"},{"id":"shi","label":"Straddle upper breakeven = K + cost","expr":"k+sc","format":"money"},{"id":"sprofit","label":"Straddle profit at expiry","expr":"abs(st-k)-sc","format":"money"},{"id":"tc","label":"Strangle cost","expr":"cc+pp","format":"money"},{"id":"tlo","label":"Strangle lower breakeven = Kp - cost","expr":"kp-tc","format":"money"},{"id":"thi","label":"Strangle upper breakeven = Kc + cost","expr":"kc+tc","format":"money"},{"id":"tprofit","label":"Strangle profit at expiry","expr":"max(kp-st, 0)+max(st-kc, 0)-tc","format":"money"}],"results":["sprofit","tprofit","slo","shi","tlo","thi"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"sc":9,"slo":91,"shi":109,"sprofit":3,"tc":4.3,"tlo":90.7,"thi":109.3,"tprofit":2.7}},"finder":{"finds":"Profit and breakevens for a bet on a big move","needs":"Strikes, premiums, price at expiry"},"related":[{"slug":"option-payoffs","name":"Call and Put Payoffs and Profit"},{"slug":"bull-call-spread","name":"Bull Call Spread"},{"slug":"collar-payoff","name":"Collar (Protective Put Financed by a Covered Call)"}],"related_ids":["F325","F327","F328"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Straddle\xa0profit</mtext><mo>=</mo><mi mathvariant=\\"normal\\">\u2223</mi><msub><mi>S</mi><mi>T</mi></msub><mo>\u2212</mo><mi>K</mi><mi mathvariant=\\"normal\\">\u2223</mi><mo>\u2212</mo><mo stretchy=\\"false\\">(</mo><mi>C</mi><mo>+</mo><mi>P</mi><mo stretchy=\\"false\\">)</mo></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Straddle profit}=|S_{T}-K|-(C+P)</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"sbc-adjusted-fcf","name":"Stock-Based Compensation Adjusted Free Cash Flow"},"next":{"slug":"straight-line-depreciation","name":"Straight-Line Depreciation"},"lesson":null,"total":522}')}}]);